cd /workspaces/semio && cat > /tmp/diag-settings.ts << 'SCRIPT'
import { chromium } from '@playwright/test';

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1400, height: 900 } });

  // Capture console errors
  const errors: string[] = [];
  page.on('console', msg => {
    if (msg.type() === 'error') errors.push(msg.text());
  });
  page.on('pageerror', err => errors.push(`PAGE ERROR: ${err.message}`));

  await page.goto('http://localhost:5173/');
  await page.waitForLoadState('domcontentloaded');
  await page.waitForTimeout(2000);

  // Import kit
  const zipPath = '/workspaces/semio/semio/assets/semio/metabolism.zip';
  const fileInput = page.locator('[id="semio.sketchpad.app.home.importKit"]');
  await fileInput.waitFor({ timeout: 10000 });
  await fileInput.setInputFiles(zipPath);
  await fileInput.evaluate(el => el.dispatchEvent(new Event('change', { bubbles: true })));

  const metabolismText = page.getByText('Metabolism', { exact: true }).first();
  await metabolismText.waitFor({ state: 'visible', timeout: 60000 });
  await page.waitForTimeout(500);

  // Navigate to kit
  const tableRow = page.locator('tr[data-row-id]').filter({ hasText: 'Metabolism' }).first();
  if (await tableRow.isVisible().catch(() => false)) {
    await tableRow.dblclick({ force: true });
  } else {
    await page.getByText('Metabolism').first().dblclick({ force: true });
  }
  await page.waitForURL(/.*kits\/.+/, { timeout: 30000 });
  await page.waitForTimeout(3000);

  // First check: Kit settings
  console.log('=== Checking KIT settings ===');
  const kitSettingsToggle = page.locator('[id="semio.sketchpad.navbar.panelToggle.settings"]');
  if (await kitSettingsToggle.isVisible().catch(() => false)) {
    await kitSettingsToggle.click();
    await page.waitForTimeout(1000);
    const kitSettingsPanel = page.locator('[data-panel="rightSidePanel"]');
    const kitSettingsHTML = await kitSettingsPanel.innerHTML().catch(() => 'NOT FOUND');
    console.log('Kit settings panel found:', kitSettingsHTML.length > 0 ? 'YES' : 'NO');
    console.log('Kit settings HTML length:', kitSettingsHTML.length);
    // Count TreeRow elements 
    const kitTreeRows = await kitSettingsPanel.locator('[data-slot="tree-row"]').count().catch(() => 0);
    console.log('Kit settings TreeRow count:', kitTreeRows);
    // Close settings
    await kitSettingsToggle.click();
    await page.waitForTimeout(500);
  } else {
    console.log('Kit settings toggle NOT VISIBLE');
  }

  // Navigate to design
  const allRowIds = await page.evaluate(() => Array.from(document.querySelectorAll('[data-row-id]')).map(el => el.getAttribute('data-row-id')));
  const designRowIds = allRowIds.filter(id => id?.startsWith('design-'));
  console.log('Design row count:', designRowIds.length);

  if (designRowIds.length > 0) {
    await page.evaluate((rowId) => {
      const row = document.querySelector(`[data-row-id="${rowId}"]`);
      if (row) row.dispatchEvent(new MouseEvent('dblclick', { bubbles: true, cancelable: true, view: window }));
    }, designRowIds[0]);
  }

  await page.waitForURL(/\/designs\//, { timeout: 30000 });
  await page.waitForTimeout(5000);

  // Check: Design settings
  console.log('=== Checking DESIGN settings ===');
  console.log('Current URL:', page.url());

  const designSettingsToggle = page.locator('[id="semio.sketchpad.navbar.panelToggle.settings"]');
  if (await designSettingsToggle.isVisible().catch(() => false)) {
    await designSettingsToggle.click();
    await page.waitForTimeout(1000);

    const designSettingsPanel = page.locator('[data-panel="rightSidePanel"]');
    const panelVisible = await designSettingsPanel.isVisible().catch(() => false);
    console.log('Design settings panel visible:', panelVisible);

    if (panelVisible) {
      const designSettingsHTML = await designSettingsPanel.innerHTML().catch(() => 'NOT FOUND');
      console.log('Design settings HTML length:', designSettingsHTML.length);
      const designTreeRows = await designSettingsPanel.locator('[data-slot="tree-row"]').count().catch(() => 0);
      console.log('Design settings TreeRow count:', designTreeRows);

      // Check for specific controls
      const toggleGroups = await designSettingsPanel.locator('[data-slot="toggle-group"]').count().catch(() => 0);
      console.log('Toggle groups:', toggleGroups);
      const selects = await designSettingsPanel.locator('[data-slot="select"]').count().catch(() => 0);
      console.log('Selects:', selects);
      const toggles = await designSettingsPanel.locator('[data-slot="toggle"]').count().catch(() => 0);
      console.log('Toggles:', toggles);

      // Get text content
      const textContent = await designSettingsPanel.textContent().catch(() => '');
      console.log('Text content preview:', textContent?.substring(0, 500));

      // Take screenshot  
      await page.screenshot({ path: '/tmp/design-settings.png', fullPage: false });
      console.log('Screenshot saved to /tmp/design-settings.png');
    } else {
      console.log('Design settings panel NOT visible!');
      // Check what's in the DOM
      const rightPanels = await page.locator('[data-panel]').evaluateAll(els => els.map(e => ({ panel: e.getAttribute('data-panel'), visible: e.offsetParent !== null })));
      console.log('All panels:', JSON.stringify(rightPanels));
    }
  } else {
    console.log('Design settings toggle NOT visible!');
  }

  console.log('\n=== Errors ===');
  errors.forEach(e => console.log('ERROR:', e));
  console.log('Total errors:', errors.length);

  await browser.close();
})();
SCRIPT
