cat > /tmp/diag2.mjs << 'EOFSCRIPT'
import { chromium } from '/workspaces/semio/node_modules/playwright/index.mjs';
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1400, height: 900 } });
const errors = [];
page.on('console', msg => { if (msg.type() === 'error') errors.push(msg.text()); });
page.on('pageerror', err => errors.push('PAGE_ERR: ' + err.message));

await page.goto('http://localhost:5174/');
await page.waitForLoadState('domcontentloaded');
await page.waitForTimeout(3000);

const zipPath = '/workspaces/semio/semio/assets/semio/metabolism.zip';
const fileInput = page.locator('[id="semio.sketchpad.app.home.importKit"]');
await fileInput.setInputFiles(zipPath);
await fileInput.evaluate(el => el.dispatchEvent(new Event('change', { bubbles: true })));
const metabolismText = page.getByText('Metabolism', { exact: true }).first();
await metabolismText.waitFor({ state: 'visible', timeout: 60000 });
await page.waitForTimeout(500);

const tableRow = page.locator('tr[data-row-id]').filter({ hasText: 'Metabolism' }).first();
if (await tableRow.isVisible().catch(() => false)) {
  await tableRow.dblclick({ force: true });
} else {
  await page.getByText('Metabolism').first().dblclick({ force: true });
}
await page.waitForURL(/.*kits\/.+/, { timeout: 30000 });
await page.waitForTimeout(3000);

// Navigate to design
const allRowIds = await page.evaluate(() => Array.from(document.querySelectorAll('[data-row-id]')).map(el => el.getAttribute('data-row-id')));
const designRowIds = allRowIds.filter(id => id && id.startsWith('design-'));
console.log('Design rows:', designRowIds.length);
if (designRowIds.length > 0) {
  await page.evaluate((rowId) => {
    const row = document.querySelector(`[data-row-id="${rowId}"]`);
    if (row) row.dispatchEvent(new MouseEvent('dblclick', { bubbles: true, cancelable: true, view: window }));
  }, designRowIds[0]);
}
await page.waitForURL(/designs/, { timeout: 30000 });
await page.waitForTimeout(8000);

// Check design settings toggle state
console.log('=== DESIGN SETTINGS TOGGLE ===');
const dToggle = page.locator('[id="semio.sketchpad.navbar.panelToggle.settings"]');
const toggleInfo = await dToggle.evaluate(el => ({
  tagName: el.tagName,
  visible: el.offsetParent !== null,
  rect: el.getBoundingClientRect(),
  classes: el.className,
  disabled: el.getAttribute('disabled'),
  ariaDisabled: el.getAttribute('aria-disabled'),
  dataState: el.getAttribute('data-state'),
  childHTML: el.innerHTML.substring(0, 300),
})).catch(e => 'ERR: ' + e.message);
console.log('Toggle info:', JSON.stringify(toggleInfo, null, 2));

// Force click with JS
await dToggle.click({ force: true, timeout: 5000 }).catch(e => console.log('Click error:', e.message));
await page.waitForTimeout(2000);

// Check if settings panel appeared
const panel = page.locator('[data-panel="rightSidePanel"]');
const pv = await panel.isVisible().catch(() => false);
console.log('Panel visible after force click:', pv);
if (pv) {
  const rows = await panel.locator('[data-slot="tree-row"]').count().catch(() => -1);
  console.log('Design TreeRow count:', rows);
  const content = await panel.locator('[data-slot="side-panel-content"]').innerHTML().catch(() => 'NONE');
  console.log('Content length:', content.length);
  console.log('Content:', content.substring(0, 500));
} else {
  // Maybe settings is already shown somewhere
  const allPanels = await page.locator('[data-panel]').evaluateAll(els => 
    els.map(e => ({ p: e.getAttribute('data-panel'), v: e.offsetParent !== null, h: e.innerHTML.length }))
  );
  console.log('All panels:', JSON.stringify(allPanels));
}

console.log('=== ERRORS ===');
errors.forEach(e => console.log('ERR:', e.substring(0,200)));
console.log('Total:', errors.length);
await browser.close();
