import { chromium } from '/workspaces/semio/node_modules/playwright/index.mjs';
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1400, height: 900 } });
const errors = [];
page.on('pageerror', err => errors.push('PAGE_ERR: ' + err.message));

await page.goto('http://localhost:5174/');
await page.waitForLoadState('domcontentloaded');
await page.waitForTimeout(3000);

// Import and navigate using seed pattern
const zipPath = '/workspaces/semio/semio/assets/semio/metabolism.zip';
const fileInput = page.locator('[id="semio.sketchpad.app.home.importKit"]');
await fileInput.setInputFiles(zipPath);
await fileInput.evaluate(el => el.dispatchEvent(new Event('change', { bubbles: true })));
await page.waitForTimeout(15000);
console.log('Step 1: Kit imported, URL:', page.url());

// Check if we need to reload
const metabolismEl = page.getByText('Metabolism', { exact: true }).first();
const metVisible = await metabolismEl.isVisible().catch(() => false);
console.log('Step 2: Metabolism visible:', metVisible);

if (metVisible) {
  await metabolismEl.dblclick({ force: true }).catch(() => {});
  await page.waitForTimeout(3000);
  console.log('Step 3: After kit click, URL:', page.url());
}

// Check if we're on kit page
if (page.url().includes('/kits/')) {
  // Look for design rows
  const designIds = await page.evaluate(() => 
    Array.from(document.querySelectorAll('[data-row-id]'))
      .map(e => e.getAttribute('data-row-id'))
      .filter(id => id && id.startsWith('design-'))
  );
  console.log('Step 4: Design IDs:', designIds);

  if (designIds.length > 0) {
    await page.evaluate(id => {
      const el = document.querySelector(`[data-row-id="${id}"]`);
      if (el) el.dispatchEvent(new MouseEvent('dblclick', { bubbles: true, cancelable: true, view: window }));
    }, designIds[0]);
    await page.waitForTimeout(8000);
    console.log('Step 5: Design page URL:', page.url());

    // Now check if settings toggle exists and works
    const toggleEl = page.locator('[id="semio.sketchpad.navbar.panelToggle.settings"]');
    const toggleCount = await toggleEl.count();
    console.log('Step 6: Settings toggles found:', toggleCount);

    if (toggleCount > 0) {
      const info = await toggleEl.first().evaluate(el => ({
        tag: el.tagName,
        rect: JSON.stringify(el.getBoundingClientRect()),
        visible: el.offsetParent !== null,
        state: el.getAttribute('data-state'),
        slot: el.getAttribute('data-slot'),
      }));
      console.log('Step 7: Toggle info:', JSON.stringify(info));

      // Try clicking child button instead
      const innerButton = toggleEl.locator('button').first();
      const btnCount = await innerButton.count();
      console.log('Step 8: Inner buttons:', btnCount);

      if (btnCount > 0) {
        await innerButton.click({ force: true }).catch(e => console.log('Click inner err:', e.message));
      } else {
        await toggleEl.first().click({ force: true }).catch(e => console.log('Click err:', e.message));
      }

      await page.waitForTimeout(2000);
      const panel = page.locator('[data-panel="rightSidePanel"]');
      const pvCount = await panel.count();
      console.log('Step 9: Right panels:', pvCount);
      console.log('Step 9b: Panel visible:', await panel.first().isVisible().catch(() => false));

      if (pvCount > 0 && await panel.first().isVisible().catch(() => false)) {
        const rows = await panel.locator('[data-slot="tree-row"]').count().catch(() => -1);
        console.log('Step 10: TreeRow count:', rows);
        const txt = await panel.first().textContent().catch(() => '').then(t => t.substring(0,500));
        console.log('Step 10b: Text:', txt);
      }
    }
  }
}

console.log('=== ERRORS ===');
errors.forEach(e => console.log('ERR:', e.substring(0,300)));
console.log('Total errors:', errors.length);
await browser.close();
