cd /workspaces/semio && python3 -c "
import json
# Read element translations (English)
with open('elements/ui/index.tsx') as f:
    content = f.read()
# Find the English JSON block
import re
m = re.search(r'en:\s*\{\s*translation:\s*JSON\.parse\(String\.raw\x60(.*?)\x60\)', content, re.DOTALL)
if m:
    en_json = json.loads(m.group(1))
    # Check design settings path
    try:
        s = en_json['semio']['sketchpad']['app']
        print('Apps:', list(s.keys())[:20])
        if 'design' in s:
            d = s['design']
            print('Design keys:', list(d.keys())[:20])
            if 'settings' in d:
                ds = d['settings']
                print('Design.settings keys:', list(ds.keys())[:20])
            else:
                print('NO settings in design')
        if 'kit' in s:
            k = s['kit']
            print('Kit keys:', list(k.keys())[:20])
            if 'settings' in k:
                ks = k['settings']
                print('Kit.settings keys:', list(ks.keys())[:20])
            else:
                print('NO settings in kit')
        if 'home' in s:
            h = s['home']
            if 'settings' in h:
                hs = h['settings']
                print('Home.settings keys:', list(hs.keys())[:20])
            else:
                print('NO settings in home')
    except KeyError as e:
        print(f'Missing key: {e}')

    # Check the shared settings path
    try:
        ss = en_json['semio']['sketchpad']['settings']
        print('Shared settings keys:', list(ss.keys())[:20])
    except KeyError as e:
        print(f'Missing shared settings key: {e}')
else:
    print('Could not find en translation')
"

