// Find lines where app.design ends
// DE block: line 2169 starts 'design': {
// EN block: starts around 7145
// Find the toolbar key (last key) and its closing brace

function findEndOfSection(startLine) {
  let depth = 0;
  let started = false;
  for (let i = startLine - 1; i < lines.length; i++) {
    const line = lines[i];
    for (const ch of line) {
      if (ch === '{') { depth++; started = true; }
      if (ch === '}') { depth--; }
      if (started && depth === 0) {
        return i + 1; // 1-indexed
      }
    }
  }
  return -1;
}

