const blocks = [...content.matchAll(/translation:\s*JSON\.parse\(String\.raw\x60([^]*?)\x60\)/g)];
for (let i = 0; i < blocks.length; i++) {
  const bundle = JSON.parse(blocks[i][1]);
  const panelToggle = bundle.semio?.sketchpad?.navbar?.panelToggle;
  console.log('Block', i + 1, 'panelToggle keys:', panelToggle ? Object.keys(panelToggle) : 'NONE');
  if (panelToggle?.toolbar) console.log('  toolbar:', JSON.stringify(panelToggle.toolbar));
  if (panelToggle?.details) console.log('  details:', JSON.stringify(panelToggle.details));
  if (panelToggle?.tools) console.log('  tools:', JSON.stringify(panelToggle.tools));
}
