    if (designSettings?.language) console.log('  language.label.normal:', designSettings.language.label.normal);
    if (designSettings?.device) console.log('  device.label.normal:', designSettings.device.label.normal);
    if (designSettings?.expertise) console.log('  expertise.label.normal:', designSettings.expertise.label.normal);
    if (designSettings?.mode) console.log('  mode.label.normal:', designSettings.mode.label.normal);
    if (designSettings?.panel) console.log('  panel keys:', Object.keys(designSettings.panel));
  } catch(e) {
    console.error('Block', i + 1, 'PARSE ERROR:', e.message);
  }
}
